import{at as e,it as t,o as n,vt as r}from"./chunks/framework.DQt_9H6f.js";var i=JSON.parse(`{"title":"Polish a draft","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workflows/polish-a-draft.md","filePath":"guide/workflows/polish-a-draft.md"}`),a={name:`guide/workflows/polish-a-draft.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="polish-a-draft" tabindex="-1">Polish a draft <a class="header-anchor" href="#polish-a-draft" aria-label="Permalink to “Polish a draft”">​</a></h1><p>Once the results are in, a polish rewrites a LaTeX draft for clarity while keeping the math, the citations and the structure. There is no polish program: ask the assistant.</p><h2 id="ask-for-it" tabindex="-1">Ask for it <a class="header-anchor" href="#ask-for-it" aria-label="Permalink to “Ask for it”">​</a></h2><p>In the TeXRA panel or <code>texra</code> in a terminal:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Polish section 2 of main.tex for clarity and flow. Keep every equation, label and citation as it is. Compile when you are done and show me a latexdiff against the version in git.</span></span></code></pre></div><p>From a script or CI:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --instruction</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Proofread paper.tex: fix typos, grammar and LaTeX syntax only. Compile it with latexmk.&quot;</span></span></code></pre></div><p>The assistant edits the file in place with its file tools, compiles it with <code>latexmk</code>, and runs <code>latexdiff</code> when you ask for a marked-up PDF. Each edit asks for approval under your <a href="./../configuration.html">approval policy</a>, with a preview of the change.</p><h2 id="getting-a-careful-result" tabindex="-1">Getting a careful result <a class="header-anchor" href="#getting-a-careful-result" aria-label="Permalink to “Getting a careful result”">​</a></h2><ul><li><strong>Commit first.</strong> The edits land in your files; <code>git diff</code> shows them and <code>git checkout</code> undoes them.</li><li><strong>Say how far to go.</strong> &quot;Proofread&quot; changes wording and formatting; &quot;polish&quot; may rewrite sentences and paragraphs; &quot;expand the derivation of (12)&quot; adds content.</li><li><strong>Ask for a second look.</strong> &quot;Then review your changes against the original and revert any the instruction did not ask for&quot; has the assistant check its own work, with a fresh helper agent if you ask for one.</li><li><strong>Ask for alternatives.</strong> &quot;Try this three ways in separate copies and keep the best&quot; has it work in copies of the project and write only the winner.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to “See also”">​</a></h2><ul><li><a href="./../programs.html">The assistant and programs</a>: <code>annotate</code> reviews a draft without rewriting it</li><li><a href="./../latex-diff.html">LaTeX diff</a>: what the marked-up PDF shows</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};